-- then hand-edited where marked: this header and the tail. The snapshot is as generated. Additive:
-- one new table and its grant; no existing row changes, so no reset (docs/RESET.md).
--
-- - signup_allowlist: the numbers that may complete the 본인확인 during the closed test, each as
--   the keyed hash of its digits alone (330-8, ADR-0071 — never the number), with when it was
--   added. No memo and no adder (330-10): the admin and the reason are the `signup_allowlist_add`
--   record in admin_actions. The list applies while it holds a row (330-3) and is emptied at
--   public launch by another admin's approval (330-2, 330-4).
-- - No enum, release setting, retention kind or CHECK of another table: the admin action types
--   are varchar values (@buddha/shared ADMIN_ACTION_TYPES) and the clear's approval kind is
--   approval_requests.kind's (`signup_allowlist_clear`).
CREATE TABLE "signup_allowlist" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"phone_hash" varchar(64) NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "signup_allowlist_phone_hash_unique" UNIQUE("phone_hash"),
	CONSTRAINT "signup_allowlist_phone_hash_check" CHECK ("signup_allowlist"."phone_hash" ~ '^[0-9a-f]{64}$')
);--> statement-breakpoint
